    #[doc = r" supervision's own completion. The bridge cancelling its waiter is a"]
    #[doc = r" rejection on exactly one path: the host freed the client while the"]
    #[doc = r" wait was pending, reported as `not-connected`. The host tearing down"]
    #[doc = r" after the call returned is not awaited here and is not claimed. A"]
    #[doc = r" manual `connect()` drives one connection outside supervision and never"]
    #[doc = r" touches this observation."]
    #[doc = r""]
    #[doc = r" Rejects with `invalid-argument` when `run()` was never called."]
    # [wasm_bindgen (js_name = waitForRunCompletion , unchecked_return_type = "Promise<RunCompletionResult>")]
